 "content": "from collections import deque


def transform(grid):
    """Repeat each colored seed tile through its surrounding zero rectangle."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 8 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            colored = [(y,x) for y,x in cells if grid[y][x] != 0]
            if not colored:
                continue
            r0, r1 = min(y for y,x in colored), max(y for y,x in colored)
            c0, c1 = min(x for y,x in colored), max(x for y,x in colored)
            tile = [grid[y][c0:c1+1] for y in range(r0,r1+1)]
            for y,x in cells:
                out[y][x] = tile[(y-r0) % len(tile)][(x-c0) % len(tile[0])]
    return out
